    if (c.type === 'unsubscribe') {
      action = 'suppressed';
      out.suppress.push({ value: c.email, type: 'email', reason: 'unsubscribe_reply', source: 'inbox', added_at: ts, lead_id: c.lead ? c.lead.lead_id : '' });
