      out.hardBounces++;
      action = 'suppressed';
      if (c.email) out.suppress.push({ value: c.email, type: 'email', reason: 'hard_bounce', source: 'inbox', added_at: ts, lead_id: c.lead ? c.lead.lead_id : '' });
